using Xunit;

namespace CSJS.Core.Tests;

/// <summary>
/// The React, Vue, and Angular bindings under <c>bindings/</c>, generated by <c>cs2js add</c>
/// from each framework's published typings.
/// <para>
/// Each test compiles the shipped file together with a small component and checks the emitted
/// JavaScript is what a JavaScript developer would have written. The same programs were run
/// against the real packages under jsdom when the bindings were generated (see
/// <c>docs/bindings.md</c>); this keeps them compiling and transpiling without the network.
/// </para>
/// </summary>
public class FrameworkBindingsTests
{
    [Fact]
    public void ReactComponentTranspilesToHooksAndCreateElement()
    {
        const string program = """
            using System;
            using CSJS;
            using CSJS.Browser;
            using Bindings.React;

            [JsExport]
            public static class App
            {
                public static object Counter(object props)
                {
                    var (count, setCount) = React.UseState(0);
                    React.UseEffect(() => Console.WriteLine($"rendered with {count}"), new object[] { count });
                    React.UseEffect(() =>
                    {
                        Console.WriteLine("mounted");
                        return () => Console.WriteLine("unmounted");
                    }, new object[0]);

                    return React.CreateElement("div", null,
                        React.CreateElement("h1", null, $"Count: {count}"),
                        React.CreateElement("button", new InputHTMLAttributes<Element> { OnClick = _ => setCount(count + 1) }, "+1"));
                }

                public static object Root() => React.CreateElement<object>(React.Fragment, null, "hello");
            }
            """;

        var js = Transpile(program, "react/React.cs");

        Js.Contains("import { Fragment as fragment, createElement, useEffect, useState } from 'react';", js);
        Js.Contains("const [count, setCount] = useState(0);", js);
        Js.Contains("useEffect(() => console.log(`rendered with ${count}`), [count]);", js);
        Js.Contains("return () => console.log('unmounted');", js);
        Js.Contains("createElement('button', { onClick: (_) => setCount(count + 1) }, '+1')", js);
        Js.Contains("createElement(fragment, null, 'hello')", js);
    }

    [Fact]
    public void VueComponentTranspilesToTheCompositionApi()
    {
        const string program = """
            using System;
            using CSJS;
            using Bindings.Vue;

            [JsExport]
            public static class App
            {
                public static object Counter() => Vue.DefineComponent<object, object, object>((props, context) =>
                {
                    var count = Vue.Ref(0);
                    var doubled = Vue.Computed<double>(_ => count.Value * 2);
                    Vue.OnMounted((Action)(() => Console.WriteLine("mounted")));

                    return () => Vue.H("button", (object)new { onClick = (Action)(() => count.Value++) },
                        (object)$"{count.Value} doubled is {doubled.Value}");
                });

                public static void Mount(string selector)
                {
                    var app = Vue.CreateApp((FunctionalComponent<object, object, object, object>)Counter());
                    app.Mount(selector);
                }
            }
            """;

        var js = Transpile(program, "vue/Vue.cs");

        Js.Contains("import { computed, createApp, defineComponent, h, onMounted, ref } from 'vue';", js);
        Js.Contains("const count = ref(0);", js);
        Js.Contains("const doubled = computed((_) => count.value * 2);", js);
        Js.Contains("h('button', { onClick: (() => count.value++) }, `${count.value} doubled is ${doubled.value}`)", js);
        Js.Contains("const app = createApp(App.Counter());", js);
        Js.Contains("app.mount(selector);", js);
    }

    [Fact]
    public void AngularComponentTranspilesToDecoratorCallAndBootstrap()
    {
        const string program = """
            using System.Threading.Tasks;
            using CSJS;
            using Bindings.Core;
            using Bindings.PlatformBrowser;

            public class Hello
            {
                public WritableSignal<double> Count = Core.Signal(0.0);
                public void Increment() => Count.Update(c => c + 1);
            }

            [JsExport]
            public static class Main
            {
                public static Task<Bindings.PlatformBrowser.ApplicationRef> Start()
                {
                    Component.Call((Component)(object)new
                    {
                        selector = "app-hello",
                        template = "<button (click)=\"Increment()\">clicked {{ Count() }}</button>",
                    })(typeof(Hello));

                    return PlatformBrowser.BootstrapApplication((Bindings.PlatformBrowser.Type<object>)(object)typeof(Hello));
                }
            }
            """;

        var js = Transpile(program, "angular/Core.cs", "angular/PlatformBrowser.cs");

        Js.Contains("import { Component, signal } from '@angular/core';", js);
        Js.Contains("import { bootstrapApplication } from '@angular/platform-browser';", js);
        Js.Contains("Count = signal(0);", js);
        Js.Contains("this.Count.update((c) => c + 1);", js);
        Js.Contains("Component({ selector: 'app-hello', template: ", js);
        Js.Contains("})(Hello);", js);
        Js.Contains("return bootstrapApplication(Hello);", js);
    }

    private static string Transpile(string program, params string[] bindingFiles)
    {
        var documents = new List<SourceDocument> { new("App.cs", program) };
        foreach (var file in bindingFiles)
        {
            var path = Path.Combine(FindBindingsDirectory(), file.Replace('/', Path.DirectorySeparatorChar));
            documents.Add(new SourceDocument(Path.GetFileName(path), File.ReadAllText(path)));
        }

        var options = new TranspileOptions { EmitSourceMap = false, EmitTypeDefinitions = false, StrictWarnings = true };
        var result = new Transpiler(options).Transpile(documents);

        // Strict: the shipped bindings must compile without a single warning.
        Assert.True(result.Success,
            "Transpilation failed:\n  " + string.Join("\n  ", result.Diagnostics.Take(20).Select(e => e.ToString())));
        return result.Modules.Single(m => m.FileName == "App.js").JavaScript;
    }

    private static string FindBindingsDirectory()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            var candidate = Path.Combine(directory.FullName, "bindings");
            if (File.Exists(Path.Combine(candidate, "react", "React.cs"))) return candidate;
        }
        throw new DirectoryNotFoundException("Could not locate the bindings/ directory.");
    }
}
